-- 📚 꼭집 주거 사전 — 재당첨 제한 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.5초 · 결과:
-- {"anns": 268, "by_std": {"SH 고유": 2, "공공임대(6·10·50년)": 16, "국민임대": 101, "매입임대": 77, "영구임대": 29, "전세임대": 4, "통합공공임대": 4, "행복주택": 29, "행복주택(신혼희망)": 6}, "재당첨제한": 5, "재당첨제한_ex": ["2015122300019919", "0000061177", "0000061176"], "부적격1년": 1, "부적격1년_ex": ["0000061177"], "미입주3년": 0, "미입주3년_ex": null}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where true),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where true group by 1)q),'재당첨제한',(select count(distinct announcement_id) from y where true and t~'재당첨\s*제한'),'재당첨제한_ex',(select json_agg(i) from(select distinct announcement_id i from y where true and t~'재당첨\s*제한' order by 1 desc limit 3)q),'부적격1년',(select count(distinct announcement_id) from y where true and t~'부적격[^.]{0,80}1\s*년'),'부적격1년_ex',(select json_agg(i) from(select distinct announcement_id i from y where true and t~'부적격[^.]{0,80}1\s*년' order by 1 desc limit 3)q),'미입주3년',(select count(distinct announcement_id) from y where true and t~'(미입주|입주하지\s*않)[^.]{0,80}3\s*년'),'미입주3년_ex',(select json_agg(i) from(select distinct announcement_id i from y where true and t~'(미입주|입주하지\s*않)[^.]{0,80}3\s*년' order by 1 desc limit 3)q))j;
